import{_ as t,c as o,o as r,ae as a}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse(`{"title":"Get Customer Invoices","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-customer-invoices","title":"Get All Customer Invoices","description":"Retrieve all invoices for the authenticated customer's orders.","request":"GET /api/shop/customer-invoices\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 5,\\n    \\"incrementId\\": \\"5\\",\\n    \\"state\\": \\"paid\\",\\n    \\"emailSent\\": true,\\n    \\"totalQty\\": 1,\\n    \\"orderCurrencyCode\\": \\"USD\\",\\n    \\"subTotal\\": 24.99,\\n    \\"baseSubTotal\\": 24.99,\\n    \\"grandTotal\\": 34.99,\\n    \\"baseGrandTotal\\": 34.99,\\n    \\"shippingAmount\\": 10,\\n    \\"baseShippingAmount\\": 10,\\n    \\"taxAmount\\": 0,\\n    \\"baseTaxAmount\\": 0,\\n    \\"discountAmount\\": 0,\\n    \\"baseDiscountAmount\\": 0,\\n    \\"shippingTaxAmount\\": 0,\\n    \\"baseShippingTaxAmount\\": 0,\\n    \\"subTotalInclTax\\": 24.99,\\n    \\"baseSubTotalInclTax\\": 24.99,\\n    \\"shippingAmountInclTax\\": 10,\\n    \\"baseShippingAmountInclTax\\": 10,\\n    \\"reminders\\": 0,\\n    \\"createdAt\\": \\"2026-07-21T17:58:29+05:30\\",\\n    \\"updatedAt\\": \\"2026-07-21T17:58:30+05:30\\",\\n    \\"downloadUrl\\": \\"https://yourstore.com/api/shop/customer-invoices/5/pdf\\",\\n    \\"items\\": [\\n      \\"/api/customer_invoice_items/11\\"\\n    ],\\n    \\"addresses\\": [\\n      \\"/api/customer_invoice_addresses/210\\",\\n      \\"/api/customer_invoice_addresses/211\\"\\n    ]\\n  }\\n]\\n","commonErrors":[{"error":"403 Forbidden","cause":"Missing or invalid customer Bearer token","solution":"Login and provide a valid customer authentication token"},{"error":"401 Unauthorized","cause":"Storefront key is missing or invalid","solution":"Provide a valid X-STOREFRONT-KEY header"},{"error":"Empty array","cause":"The customer has no invoiced orders yet","solution":"An order is invoiced by the store, not by the shopper — there is nothing to fix client-side"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customer-invoices/get-customer-invoices.md","filePath":"api/rest-api/shop/customer-invoices/get-customer-invoices.md"}`),d={name:"api/rest-api/shop/customer-invoices/get-customer-invoices.md"};function n(i,e,s,c,l,h){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="get-customer-invoices" tabindex="-1">Get Customer Invoices <a class="header-anchor" href="#get-customer-invoices" aria-label="Permalink to &quot;Get Customer Invoices&quot;">​</a></h1><p>Retrieve all invoices belonging to the authenticated customer&#39;s orders. This is a <strong>read-only</strong> API — customers can only view their own invoices. Invoices are automatically scoped to the authenticated customer via the order relationship.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/customer-invoices</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><p>A bare JSON array of invoices. There is no wrapper object and no pagination metadata — the endpoint returns every invoice of the customer&#39;s orders.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Invoice ID. Use it on <a href="/api/rest-api/shop/customer-invoices/get-customer-invoice.html">Get Invoice</a> and the PDF route.</td></tr><tr><td><code>incrementId</code></td><td>string</td><td>Invoice number shown to the customer.</td></tr><tr><td><code>state</code></td><td>string</td><td>Invoice state — see below.</td></tr><tr><td><code>emailSent</code></td><td>boolean</td><td>Whether the invoice email has gone out.</td></tr><tr><td><code>totalQty</code></td><td>integer</td><td>Units covered by this invoice.</td></tr><tr><td><code>orderCurrencyCode</code></td><td>string</td><td>Currency the order was placed in.</td></tr><tr><td><code>subTotal</code> / <code>baseSubTotal</code> / <code>subTotalInclTax</code> / <code>baseSubTotalInclTax</code></td><td>float</td><td>Line total, before and including tax, in order and base currency.</td></tr><tr><td><code>grandTotal</code> / <code>baseGrandTotal</code></td><td>float</td><td>Invoice total.</td></tr><tr><td><code>shippingAmount</code> / <code>baseShippingAmount</code> / <code>shippingAmountInclTax</code> / <code>baseShippingAmountInclTax</code></td><td>float</td><td>Shipping charged on this invoice.</td></tr><tr><td><code>taxAmount</code> / <code>baseTaxAmount</code> / <code>shippingTaxAmount</code> / <code>baseShippingTaxAmount</code></td><td>float</td><td>Tax charged.</td></tr><tr><td><code>discountAmount</code> / <code>baseDiscountAmount</code></td><td>float</td><td>Discount applied.</td></tr><tr><td><code>reminders</code></td><td>integer</td><td>Payment reminders sent so far.</td></tr><tr><td><code>downloadUrl</code></td><td>string</td><td>Absolute URL of the PDF — the same route as <a href="/api/rest-api/shop/customer-invoices/download-customer-invoice-pdf.html">Download Invoice PDF</a>. It still requires the storefront key and the customer token, so it cannot be used as a plain link.</td></tr><tr><td><code>items</code></td><td>array</td><td>References to the invoice lines.</td></tr><tr><td><code>addresses</code></td><td>array</td><td>References to the order&#39;s billing and shipping addresses.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr></tbody></table><p>The invoiced line items are available from the parent order&#39;s own <code>items</code> block on <a href="/api/rest-api/shop/customer-orders/get-customer-order.html">Get Customer Order</a>, and on the invoice PDF. Over GraphQL the <code>customerInvoices</code> query returns them as selectable nested objects.</p><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>order_id</code></td><td>integer</td><td>Return only the invoices raised against that order. <code>orderId</code> is accepted as an alias.</td></tr><tr><td><code>state</code></td><td>string</td><td>Return only invoices in that state.</td></tr></tbody></table><p>Both narrow the same list; supplying neither returns every invoice the customer has.</p><h2 id="invoice-state-values" tabindex="-1">Invoice State Values <a class="header-anchor" href="#invoice-state-values" aria-label="Permalink to &quot;Invoice State Values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Description</th></tr></thead><tbody><tr><td><code>pending</code></td><td>Invoice raised, payment not yet recorded.</td></tr><tr><td><code>pending_payment</code></td><td>Awaiting an offline payment such as a bank transfer.</td></tr><tr><td><code>paid</code></td><td>Payment recorded in full.</td></tr><tr><td><code>overdue</code></td><td>Past the store&#39;s payment-terms window. Usually shown as a derived countdown rather than a stored value.</td></tr></tbody></table><h2 id="empty-collection" tabindex="-1">Empty Collection <a class="header-anchor" href="#empty-collection" aria-label="Permalink to &quot;Empty Collection&quot;">​</a></h2><p>A customer with no invoiced orders gets <code>200</code> with <code>[]</code>. An order is only invoiced when the store raises the invoice, so a recently placed order legitimately has none.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Billing history in the account area</strong> — one call returns every invoice; there is no pagination to walk.</li><li><strong>&quot;Pay now&quot; prompt</strong> — filter on <code>state</code> of <code>pending</code> or <code>pending_payment</code> client-side; the endpoint does the filtering only through the documented <code>?state=</code> parameter.</li><li><strong>Download link</strong> — use <code>downloadUrl</code> as the request URL, not as an anchor <code>href</code>; the PDF route needs both auth headers.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Read the line items from the parent order</strong> — <a href="/api/rest-api/shop/customer-orders/get-customer-order.html">Get Customer Order</a> carries them in full, along with the addresses captured at checkout.</li><li><strong>Present <code>incrementId</code>, not <code>id</code></strong> — the increment ID is what appears on the invoice document.</li><li><strong>Compare against the order&#39;s <code>grandTotalInvoiced</code></strong> — an order can carry several partial invoices, so a single invoice total is not the amount owed for the order.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customer-invoices/get-customer-invoice.html">Get Single Customer Invoice</a> — one invoice by id</li><li><a href="/api/rest-api/shop/customer-invoices/download-customer-invoice-pdf.html">Download Invoice PDF</a> — the invoice as a PDF stream</li><li><a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Customer Orders</a> — the customer&#39;s order history</li><li><a href="/api/rest-api/shop/customers/get-customer-profile.html">Get Customer Profile</a> — read the authenticated customer&#39;s account details</li></ul>',23)]))}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
